From e77bdd7de25af87c53da6e5a3727c028956c1e00 Mon Sep 17 00:00:00 2001
From: Shawn Walker <accumulo@shawn-walker.net>
Date: Fri, 15 Apr 2016 10:38:37 -0400
Subject: [PATCH] ACCUMULO-4191 Wrapped runnable with Trace.wrap in
 TabletServerBatchWriter to prevent loss of sendMutation events

Closes apache/accumulo#94

Signed-off-by: Josh Elser <elserj@apache.org>

diff --git a/core/src/main/java/org/apache/accumulo/core/client/impl/TabletServerBatchWriter.java b/core/src/main/java/org/apache/accumulo/core/client/impl/TabletServerBatchWriter.java
index 77d8307259..a8afa5af95 100644
--- a/core/src/main/java/org/apache/accumulo/core/client/impl/TabletServerBatchWriter.java
+++ b/core/src/main/java/org/apache/accumulo/core/client/impl/TabletServerBatchWriter.java
@@ -735,7 +735,7 @@ public class TabletServerBatchWriter {
     void queueMutations(final MutationSet mutationsToSend) throws InterruptedException {
       if (null == mutationsToSend)
         return;
-      binningThreadPool.execute(new Runnable() {
+      binningThreadPool.execute(Trace.wrap(new Runnable() {

         @Override
         public void run() {
@@ -748,7 +748,7 @@ public class TabletServerBatchWriter {
             }
           }
         }
-      });
+      }));
     }

     private void addMutations(MutationSet mutationsToSend) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the lack of proper tracing for the `Runnable` that handles mutation events in the `TabletServerBatchWriter`. Without wrapping the `Runnable` with `Trace.wrap()`, the system could lose important `sendMutation` events during their execution in a separate thread, leading to potential inconsistencies or failures in processing mutations.

        Commit message:
        ACCUMULO-4191 Wrapped runnable with Trace.wrap in
 TabletServerBatchWriter to prevent loss of sendMutation events

Closes apache/accumulo#94

Signed-off-by: Josh Elser <elserj@apache.org>  

        Patch:

     void queueMutations(final MutationSet mutationsToSend) throws InterruptedException {
       if (null == mutationsToSend)
         return;
-      binningThreadPool.execute(new Runnable() {
+      binningThreadPool.execute(Trace.wrap(new Runnable() {

         @Override
         public void run() {
           if (null != mutationsToSend) {
             try {
               log.trace("{} - binning {} mutations", Thread.currentThread().getName(), mutationsToSend.size());
               addMutations(mutationsToSend);
             } catch (Exception e) {
               updateUnknownErrors("Error processing mutation set", e);
             }
           }
         }
-      });
+      }));
     }



